BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('linux-q1', 'コンピュータとOSの中身',
   'アプリがファイルを保存するとき、アプリのプログラム自身がハードディスクの部品を直接動かしているわけではない。実際に間に立ってハードウェアを操作しているのは何か。',
   NULL::text,
   '["OS（カーネル）", "Webブラウザなどの別のアプリ", "ディスプレイの制御チップ", "インターネット経由のメーカーのサーバー"]',
   0, '[0]', 'single',
   '{"asked": "ファイル保存の実作業を、実際に誰が行っているかを問う問題。", "point": "ハードウェアに触れてよいのはOS（カーネル）だけ。アプリはOSに「お願い」しているだけ。", "kid": "アプリは「保存して」とお願いするだけで、実際にディスクの部品を動かす作業はOSが代わりにやってくれている。", "eg": "レストランで、お客（アプリ）が「これ作って」と注文しても、実際に火を使って調理するのは厨房（OS）。お客が直接コンロを触ることはない。", "terms": [["OS", "オペレーティングシステム。ハードウェアとアプリの間を仲介する基本ソフト"], ["カーネル", "OSの中でもハードウェアを直接操作する中心部分"]], "think": "なぜアプリ自身がディスクを操作しないのかがカギ。もしアプリごとにディスクの操作方法がバラバラだと、同時に2つのアプリが同じ場所に書き込んで壊してしまうかもしれない。OSが「窓口」として一本化して仲介することで、複数のアプリが安全に同じハードウェアを共有できる。", "vs": "「OSも1つのアプリの一種」と誤解しがちだが、OSは他の全アプリの下で動く特別な立場にあり、ハードウェアへの操作権を独占している点が普通のアプリと違う。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"70\" y=\"15\" width=\"200\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170\" y=\"34\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アプリ（ブラウザ・エディタなど）</text><line x1=\"170\" y1=\"45\" x2=\"170\" y2=\"63\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 57 L 170 63 L 174 57\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"70\" y=\"63\" width=\"200\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170\" y=\"82\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">OS（カーネル）＝仲介役</text><line x1=\"170\" y1=\"93\" x2=\"170\" y2=\"111\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 105 L 170 111 L 174 105\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"70\" y=\"111\" width=\"200\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"170\" y=\"130\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ハードウェア（CPU・ディスク等）</text></svg>", "opt": ["正解。ハードウェアへの実際の操作は、間に立つOS（カーネル）が代行する。", "他のアプリにはハードウェアを直接操作する権限はなく、保存作業を代行することはない。", "ディスプレイの制御チップは画面表示だけを担当し、ディスク保存の作業とは無関係。", "メーカーのサーバーはインターネット越しの別のコンピュータであり、手元のディスク操作には関与しない。"]}'),

  ('linux-q2', 'コンピュータとOSの中身',
   'もしOSが存在せず、すべてのアプリが自分自身でハードディスクやメモリを直接操作しなければならないとしたら、何が起きやすいか。',
   NULL::text,
   '["複数のアプリが同じ部品を勝手に取り合い、衝突して壊れやすくなる", "アプリの起動速度がわずかに遅くなるだけで、他は普段と変わらない", "画面の色がすべて白黒になる", "キーボードの入力だけが受け付けられなくなる"]',
   0, '[0]', 'single',
   '{"asked": "OSという仲介役がいない世界で何が起きるかを考えさせる問題。", "point": "仲介役が消えると、複数のアプリが同じハードウェアに直接群がって衝突する。", "kid": "OSがいなければ、それぞれのアプリが「自分が優先だ」とバラバラにハードウェアを触りに行き、ぶつかり合ってしまう。", "eg": "信号機（OS）のない交差点を想像する。車（アプリ）はそれぞれ好き勝手に交差点（ハードウェア）へ突っ込み、事故が起きやすくなる。", "terms": [["排他制御", "複数のプログラムが同じ資源を同時に触らないよう調整する考え方。OSが担う"]], "think": "なぜ衝突が起きるのかがカギ。ハードウェアは1つしかないのに、アプリは複数同時に動きたがる。誰かが交通整理をしないと、同じメモリ番地に別々のアプリが同時に書き込む、といった食い違いが起きる。OSはこの交通整理役を一手に引き受けることで、衝突を防いでいる。", "vs": "「OSが無くても単に不便になるだけ」という軽い理解に注意。実際には安定して動くこと自体が難しくなる、という土台の話。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"25\" y=\"15\" width=\"70\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"60\" y=\"32\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アプリA</text><rect x=\"135\" y=\"15\" width=\"70\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170\" y=\"32\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アプリB</text><rect x=\"245\" y=\"15\" width=\"70\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"280\" y=\"32\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アプリC</text><rect x=\"100\" y=\"105\" width=\"140\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"170\" y=\"122\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ハードウェア</text><line x1=\"60\" y1=\"41\" x2=\"170\" y2=\"105\" stroke=\"#c47070\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><line x1=\"170\" y1=\"41\" x2=\"170\" y2=\"105\" stroke=\"#c47070\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><line x1=\"280\" y1=\"41\" x2=\"170\" y2=\"105\" stroke=\"#c47070\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><text x=\"170\" y=\"145\" font-size=\"9\" fill=\"#c47070\" text-anchor=\"middle\" font-weight=\"normal\">全員が直接・バラバラに制御＝衝突と壊れやすさ</text></svg>", "opt": ["正解。交通整理役がいなくなり、複数のアプリが同じハードウェアを奪い合って衝突しやすくなる。", "起動速度の問題ではなく、そもそも安定して動くこと自体が難しくなる。", "画面の色数はOSの有無ではなくグラフィック機能の話で、直接の関係はない。", "キーボード入力に限らず、あらゆるハードウェアの取り合いが起きる。入力だけの問題ではない。"]}'),

  ('linux-q3', 'コンピュータとOSの中身',
   'コンピュータの中は大きく「カーネル空間」と「ユーザー空間」に分かれている。ふだん私たちが使うブラウザやエディタなどのアプリが動いているのはどちらか。',
   NULL::text,
   '["ユーザー空間", "カーネル空間", "どちらでもなく専用の第三の空間で動く", "起動直後だけカーネル空間で動き、その後ユーザー空間に移る"]',
   0, '[0]', 'single',
   '{"asked": "普段使うアプリがどちらの空間で動いているかを問う問題。", "point": "特権を持つのはカーネル空間だけ。ふつうのアプリはユーザー空間に閉じ込められている。", "kid": "コンピュータの中には「なんでもできる特別な場所（カーネル空間）」と「そこには入れない普通の場所（ユーザー空間）」があり、ブラウザやエディタのようなアプリはユーザー空間の中でしか動けない。", "eg": "会社に例えると、カーネル空間は「金庫室に入れる社員だけの区画」、ユーザー空間は「来客も通れる普通のフロア」。一般のアプリは来客と同じで、金庫室（ハードウェア）には直接入れない。", "terms": [["カーネル空間", "ハードウェアに直接触れる特権を持つ領域"], ["ユーザー空間", "特権を持たない、アプリが動く一般の領域"]], "think": "なぜ空間を分けるのかがカギ。もしどのアプリもハードウェアに直接触れてよいなら、1つのアプリのバグが暴走してハードウェア全体を巻き込んで壊す事故が起きやすい。ユーザー空間に閉じ込めて特権を与えないことで、1つのアプリが暴走しても被害をそのアプリの中にとどめやすくなる。", "vs": "「アプリが賢くなればカーネル空間に入れる」という誤解に注意。空間の区別はアプリの出来の良し悪しではなく、OSが最初から決めている仕組み上のルール。", "viz": "<svg viewBox=\"0 0 340 145\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"300\" height=\"45\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170\" y=\"38\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">カーネル空間（特権あり）</text><text x=\"170\" y=\"55\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ハードウェアに直接触れてよい場所</text><line x1=\"20\" y1=\"75\" x2=\"320\" y2=\"75\" stroke=\"#2a2f3f\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><rect x=\"20\" y=\"85\" width=\"300\" height=\"45\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170\" y=\"103\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ユーザー空間（特権なし）</text><text x=\"170\" y=\"120\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">アプリはここでしか動けない</text></svg>", "opt": ["正解。ふつうのアプリはユーザー空間でしか動けない。", "カーネル空間はOSの中心部分専用で、一般アプリはそこには入れない。", "空間は基本的にこの2種類で、専用の第三の空間が用意されているわけではない。", "起動直後だけ特権を持つ、という一時的な仕組みは存在しない。アプリは一貫してユーザー空間で動く。"]}'),

  ('linux-q4', 'コンピュータとOSの中身',
   'ユーザー空間で動くアプリが「ファイルを保存したい」など、ハードウェアが関わる作業をカーネルにお願いするときに使う、決まった呼び出し方の窓口を何と呼ぶか。',
   NULL::text,
   '["システムコール", "プロトコル", "コンパイラ", "パッケージマネージャ"]',
   0, '[0]', 'single',
   '{"asked": "アプリがカーネルに作業を依頼するときの窓口の名前を問う問題。", "point": "アプリからカーネルへの唯一の正式な依頼窓口がシステムコール。", "kid": "アプリは「ファイルを保存して」「メモリをちょうだい」のようなお願いを、システムコールという決まった呼び出し方でカーネルに伝える。カーネルはその窓口経由の頼みごとだけを受け付ける。", "eg": "役所の窓口のようなもの。住民（アプリ）は勝手に金庫（ハードウェア）へ入れず、決められた申請書（システムコール）を窓口（カーネル）に出して手続きしてもらう。", "terms": [["システムコール", "アプリがカーネルにハードウェア関連の作業を依頼するための決まった呼び出し方"]], "think": "なぜ決まった窓口を1つにするのかがカギ。窓口が1つに決まっていれば、カーネル側は「この形式の依頼だけ受け付ければよい」と管理でき、変な依頼やハードウェアへの無秩序なアクセスを防げる。アプリごとに好き勝手な方法でハードウェアに触られると、前の設問で見た衝突が再び起きてしまう。", "vs": "プロトコルと混同しやすいが、プロトコルは主にネットワーク越しの通信の取り決めで、システムコールは同じコンピュータの中でアプリとカーネルが会話する仕組みという点が違う。", "viz": "<svg viewBox=\"0 0 340 125\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"45\" width=\"110\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"75\" y=\"64\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アプリ</text><line x1=\"130\" y1=\"60\" x2=\"200\" y2=\"60\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 194 56 L 200 60 L 194 64\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"165\" y=\"52\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">お願い</text><rect x=\"200\" y=\"30\" width=\"60\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"230\" y=\"55\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">門番</text><text x=\"230\" y=\"70\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">(syscall)</text><line x1=\"260\" y1=\"60\" x2=\"320\" y2=\"60\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 314 56 L 320 60 L 314 64\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"170\" y=\"105\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">アプリは直接触れず、決まった窓口を通してだけ頼める</text></svg>", "opt": ["正解。アプリがカーネルにハードウェア関連の作業を依頼する、決まった呼び出し方。", "プロトコルは主にネットワーク通信の取り決めで、同一コンピュータ内のアプリ→カーネルの依頼窓口とは別物。", "コンパイラはソースコードを実行ファイルに変換する道具で、依頼窓口ではない。", "パッケージマネージャはソフトの導入・更新を管理する道具で、依頼窓口ではない。"]}'),

  ('linux-q5', 'コンピュータとOSの中身',
   '1つのCPUのコアしかないパソコンでも、ブラウザを開きながら音楽プレーヤーを同時に動かせるように見える。この「同時に動いているように見える」仕組みの説明として最も適切なものはどれか。',
   NULL::text,
   '["OSが各アプリに短い時間ずつ順番にCPUを割り当て、高速に切り替えている", "CPUの中で複数のアプリが実際に同時に計算を行っている", "音楽プレーヤーはCPUを使わず、スピーカーが単独で音を鳴らしている", "ブラウザと音楽プレーヤーが起動時に1つのアプリへ自動的に合体している"]',
   0, '[0]', 'single',
   '{"asked": "1コアでも複数アプリが同時に動いて見える仕組みを問う問題。", "point": "正体は「同時」ではなく「高速な順番待ちの繰り返し」。", "kid": "1つのコアは一度に1つのことしかできないけれど、OSがものすごく短い時間で「ブラウザ→音楽プレーヤー→ブラウザ→…」と目にも止まらぬ速さで切り替えているので、人間の目には同時に動いているように見える。", "eg": "1人の店員（CPUコア）が何人ものお客（アプリ）を相手にするとき、1人ずつ数秒おきに接客を切り替えていくと、離れて見ている人には「全員同時に対応している」ように見える、というイメージ。", "terms": [["スケジューリング", "OSが各アプリにCPUの使用時間を順番に割り当てる仕組み"], ["マルチタスク", "複数のアプリが同時に動いているように見える状態"]], "think": "なぜ「同時に見える」だけで実際は交代制なのかがカギ。CPUのコア数には限りがあるが、動かしたいアプリの数はそれより多いのが普通。OSが1つ1つのアプリに対してごく短い時間だけCPUを貸し、また次のアプリに貸し…と超高速に繰り返すことで、限られたコアを多くのアプリで分け合える。切り替えが速すぎて人間には気づけないだけで、実体は「順番待ち」。", "vs": "コア数が複数（マルチコアCPU）の場合は本当に同時に計算できる部分もあるが、コア数よりアプリの数が多い状況では、結局この交代制の仕組みに頼ることになる。", "viz": "<svg viewBox=\"0 0 340 125\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"25\" y=\"15\" width=\"70\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"60\" y=\"32\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アプリA</text><line x1=\"60\" y1=\"41\" x2=\"60\" y2=\"63\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 56 57 L 60 63 L 64 57\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"135\" y=\"15\" width=\"70\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170\" y=\"32\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アプリB</text><line x1=\"170\" y1=\"41\" x2=\"170\" y2=\"63\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 57 L 170 63 L 174 57\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"245\" y=\"15\" width=\"70\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"280\" y=\"32\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アプリC</text><line x1=\"280\" y1=\"41\" x2=\"280\" y2=\"63\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 276 57 L 280 63 L 284 57\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"90\" y=\"63\" width=\"160\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170\" y=\"80\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">OSが順番に少しずつCPUを割り当てる</text><text x=\"170\" y=\"105\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">同時に動いているように見えて、実は交代制</text></svg>", "opt": ["正解。OSが短い時間ずつ順番にCPUを割り当て、高速に切り替えることで同時に見せている。", "1コアは一度に1つの計算しかできず、複数アプリが実際に同時に計算しているわけではない。", "音楽プレーヤーもCPUを使ってデータを処理しており、スピーカー単独で音を鳴らしているわけではない。", "ブラウザと音楽プレーヤーが1つのアプリに合体するという仕組みは存在しない。それぞれ別のアプリのまま動く。"]}'),

  ('linux-q6', 'コンピュータとOSの中身',
   'ソフトウェアQAの仕事で「このアプリはOSのバージョンによって挙動が変わる」というバグに出会うことがある。これはアプリとOSの関係として最も適切にはどう理解できるか。',
   NULL::text,
   '["アプリはOSの窓口を介して動くため、窓口の中身がOSのバージョンで変わると影響を受けうる", "アプリはOSを経由せず単独で動くため、OSのバージョン差は本来は無関係のはずである", "OSのバージョンはディスプレイの解像度だけを変える設定で、アプリの挙動には影響しない", "アプリはOSの一部として組み込まれており、バージョンが違うと別のアプリとして扱われる"]',
   0, '[0]', 'single',
   '{"asked": "「OSのバージョンでアプリの挙動が変わる」現象を、アプリ-OSの関係から理解できるか問う問題。", "point": "アプリはOSが用意する窓口越しにハードウェアを使うので、窓口の中身が変われば影響が出うる。", "kid": "アプリは直接ハードウェアを触れず、OSの窓口（システムコールなど）を通じて動いている。OSのバージョンが変わるとその窓口の中の実装が少し変わることがあり、それがアプリの挙動の違いとして表に出てくることがある。", "eg": "レストランの厨房（OS）が新しい調理器具に入れ替わった場合、同じ注文（アプリからの依頼）をしても、出来上がる料理の細部（挙動）が少し変わることがある、というイメージ。", "terms": [["互換性", "違うバージョンのOSやソフト同士でも、同じように動作し続けられる性質"]], "think": "なぜOSのバージョン差がアプリに影響するのかがカギ。アプリは自分でハードウェアを操作せず、常にOSという仲介役に頼っている。仲介役の中身（カーネルやシステムコールの実装）が更新されると、アプリからの同じお願いに対する返事のタイミングや細かい挙動が変わることがあり、それがバグとして観測される。QA目線では「OS差分あり」の報告は、このアプリ-OS間の依存関係を疑う手がかりになる。", "vs": "「アプリはOSと無関係に単独で動く」という誤解に注意。アプリはハードウェアへの実作業をすべてOSに委ねているため、本質的にOSに依存した存在である。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"70\" y=\"15\" width=\"200\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170\" y=\"34\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アプリ（ブラウザ・エディタなど）</text><line x1=\"170\" y1=\"45\" x2=\"170\" y2=\"63\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 57 L 170 63 L 174 57\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"70\" y=\"63\" width=\"200\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170\" y=\"82\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">OS（カーネル）＝仲介役</text><line x1=\"170\" y1=\"93\" x2=\"170\" y2=\"111\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 166 105 L 170 111 L 174 105\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"70\" y=\"111\" width=\"200\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"170\" y=\"130\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ハードウェア（CPU・ディスク等）</text></svg>", "opt": ["正解。アプリはOSの窓口を介して動くため、窓口の中身が変わる（OSのバージョンが変わる）と挙動に影響が出うる。", "アプリは実際にはOSを介してハードウェアを操作しており、OSと無関係に単独で動くわけではない。", "OSのバージョンは解像度設定だけでなく、カーネルやシステムコールの実装全体を含む広い範囲を指す。", "アプリはOSに組み込まれた一部ではなく、OSの上で動く別個のソフトウェアである。"]}'),

  ('linux-q7', 'シェルとコマンドの正体',
   'ターミナルに文字を打ち込むと、その文字を受け取って解釈し、対応する処理を呼び出しているものの正体は何か。',
   NULL::text,
   '["シェルという1つのプログラム", "ターミナルというアプリ自身の内部機能そのもの", "OSのカーネルが文字を直接1文字ずつ解釈している", "キーボードのファームウェアが命令として解釈している"]',
   0, '[0]', 'single',
   '{"asked": "ターミナルに打ち込んだ文字を実際に解釈しているものの正体を問う問題。", "point": "「ターミナルで何か起きる」の実体は、シェルという1つのプログラムが動いているだけ。", "kid": "ターミナルは画面の窓口にすぎず、実際に打った文字を読んで「これはこういう意味だな」と判断しているのは、シェルという名前の1つのプログラム。", "eg": "ターミナルは受付カウンター、シェルはそのカウンターに座っている担当者。文字を読んで対応してくれるのは担当者（シェル）であって、カウンター（ターミナル）そのものではない。", "terms": [["シェル", "ユーザーが打ち込んだコマンドを解釈し、実行してくれるプログラム。bashやzshなど"], ["ターミナル", "文字の入出力をやり取りする画面・窓口"]], "think": "なぜ「ターミナル自身が処理している」わけではないのかがカギ。ターミナルはあくまで文字を表示し入力を受け取る箱にすぎない。その箱の中で実際に動いて文字を解釈するプログラムとして、別途シェルが起動している。シェルを別のプログラム（例えばbashからzshへ）に入れ替えても、同じターミナルの箱の中でそのまま動かせるのは、両者が別物だから。", "vs": "「シェル＝ターミナル」という混同が最も多い。ターミナルは窓口（箱）、シェルはその中で動く1つのプログラム、という役割の違いを区別する。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"55\" width=\"80\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"60\" y=\"74\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">あなた</text><line x1=\"100\" y1=\"70\" x2=\"140\" y2=\"70\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 134 66 L 140 70 L 134 74\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"140\" y=\"40\" width=\"90\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"185\" y=\"58\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"bold\">シェル</text><text x=\"185\" y=\"74\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">（1つの</text><text x=\"185\" y=\"86\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">プログラム）</text><line x1=\"230\" y1=\"70\" x2=\"300\" y2=\"70\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 294 66 L 300 70 L 294 74\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"300\" y=\"55\" width=\"30\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"315\" y=\"74\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">OS</text></svg>", "opt": ["正解。打ち込んだ文字を解釈しているのはシェルという1つのプログラム。", "ターミナルはあくまで入出力の窓口であり、文字の意味を解釈する機能自体は持たない。", "カーネルは文字の解釈ではなく、ハードウェアの操作を担う部分で役割が異なる。", "キーボードのファームウェアはキー入力を電気信号に変える処理までで、コマンドの意味の解釈は行わない。"]}'),

  ('linux-q8', 'シェルとコマンドの正体',
   'シェルに `ls` と打ち込んで実行すると、コンピュータの中では最終的に何が起きているか。最も適切なものを選べ。',
   NULL::text,
   '["シェルがPATHのリストから ls という実行ファイルを探し出し、実行する", "ls という単語はカーネルに直接命令として組み込まれており、探索は行われない", "シェルがインターネット経由で ls の処理をサーバーに依頼し、結果だけを受け取る", "ls という単語を読んだ瞬間、ハードディスクの全内容が自動的に画面に表示される"]',
   0, '[0]', 'single',
   '{"asked": "コマンドを打ったときに裏で起きていることの実体を問う問題。", "point": "コマンドの正体は「名前の付いた実行ファイル」。シェルはそれを探して動かしているだけ。", "kid": "`ls` はただの名前で、実体は `/bin/ls` のようにディスクのどこかに置かれた「実行できるファイル」。シェルは「ls」という名前を聞いたら、決まった場所のリスト（PATH）を順番に探して、その実行ファイルを見つけて動かしている。", "eg": "図書館の受付（シェル）に「ls という本を出して」と頼むと、受付は決まった書架のリスト（PATH）を順番に探し、見つけた本（実行ファイル）を持ってきて開いてくれる、というイメージ。", "terms": [["実行ファイル", "コンピュータが直接実行できる形式のファイル。コマンドの正体"], ["PATH", "実行ファイルを探す場所のリスト。環境変数の1つ"]], "think": "なぜ「探索してから実行」という手順が要るのかがカギ。コマンドは魔法の言葉ではなく、ディスクのどこかにある1つのファイルにすぎない。同じ名前の実行ファイルが複数の場所にあることもあるので、シェルは決められた順番（PATH）で探し、最初に見つかったものを実行する、というルールで動いている。この探索の仕組みが分かると、「コマンドが見つかりません」というエラーも、探索場所のリストに実行ファイルが無かっただけ、と理解できる。", "vs": "「コマンドはOSに最初から埋め込まれた特別な言葉」という誤解に注意。実際は単なる実行ファイルであり、自分で同じ名前・別の場所に置き換えることさえできる。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"110\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"75\" y=\"37\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">入力: ls</text><line x1=\"75\" y1=\"46\" x2=\"75\" y2=\"68\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 71 62 L 75 68 L 79 62\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"20\" y=\"68\" width=\"110\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"75\" y=\"85\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">探す（PATH）</text><line x1=\"130\" y1=\"81\" x2=\"210\" y2=\"81\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 204 77 L 210 81 L 204 85\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"210\" y=\"68\" width=\"110\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"265\" y=\"85\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">実行ファイル</text><text x=\"265\" y=\"100\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">/bin/ls</text><line x1=\"265\" y1=\"94\" x2=\"265\" y2=\"116\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 261 110 L 265 116 L 269 110\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"210\" y=\"116\" width=\"110\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1\"/><text x=\"265\" y=\"133\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">結果を画面へ</text></svg>", "opt": ["正解。シェルがPATHのリストから ls という実行ファイルを探し出し、実行する。", "ls はカーネルに直接組み込まれた特別な命令ではなく、探索して実行される1つのファイルにすぎない。", "ls の実行はインターネット通信を必要とせず、手元のコンピュータの中だけで完結する。", "実行ファイルが見つかり実行されて初めて中身の一覧が表示される。名前を読んだだけで自動表示されるわけではない。"]}'),

  ('linux-q9', 'シェルとコマンドの正体',
   'ターミナルを開いて1行ずつコマンドを打ち込み、結果を見ながら次を考えて打つ使い方と、あらかじめ手順をすべて1つのファイルに書いておいて一気に実行させる使い方がある。後者を一般に何と呼ぶか。',
   NULL::text,
   '["シェルスクリプト", "対話的シェル", "システムコール", "パイプライン"]',
   0, '[0]', 'single',
   '{"asked": "手順をあらかじめ書いておいて一気に実行させる使い方の名前を問う問題。", "point": "「打って結果を見て次を考える」が対話的、「先に全部書いて流す」がスクリプト。", "kid": "1行ずつその場で考えながら打つのが対話的シェルの使い方。逆に「まずこれ、次にこれ」という手順をあらかじめ1つのファイルにまとめて書いておき、それをまとめて流し込んで実行させるのがシェルスクリプト。", "eg": "対話的シェルは、店員に「これください」「次はこれください」とその場その場で注文するイメージ。シェルスクリプトは、あらかじめ全部の注文を書いた紙（レシピ）を渡して「この通りに全部やって」とお願いするイメージ。", "terms": [["シェルスクリプト", "シェルへの一連の指示をあらかじめファイルに書いておき、まとめて実行させるもの"], ["対話的シェル", "1行ずつ打ち込み、その場で結果を確認しながら進める使い方"]], "think": "なぜこの2つの使い方が両方要るのかがカギ。試行錯誤しながら状況を確認したいときは対話的シェルが向くが、同じ手順を毎回繰り返す（例えば自動テストの実行手順）ような場面では、1行ずつ手で打つのは手間で間違いも起きやすい。あらかじめ手順をシェルスクリプトとして書いておけば、いつでも同じ手順を正確に再現できる。QAの自動テストの多くは、実はこのシェルスクリプトの仕組みの上に成り立っている。", "vs": "システムコールと混同しないこと。システムコールはアプリがカーネルに作業を依頼する仕組みで、シェルスクリプトはシェルへの指示をまとめて書いたファイルという、まったく別のレイヤーの話。", "viz": "<svg viewBox=\"0 0 340 100\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"85\" y=\"16\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"bold\">対話的シェル</text><rect x=\"20\" y=\"26\" width=\"130\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"85\" y=\"43\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1行打つ→即実行</text><rect x=\"20\" y=\"58\" width=\"130\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"85\" y=\"75\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">結果を見て次を打つ</text><line x1=\"170\" y1=\"20\" x2=\"170\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><text x=\"255\" y=\"16\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"bold\">スクリプト</text><rect x=\"190\" y=\"26\" width=\"130\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"255\" y=\"43\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">手順を先に全部書く</text><rect x=\"190\" y=\"58\" width=\"130\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"255\" y=\"75\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">まとめて一気に実行</text></svg>", "opt": ["正解。手順をあらかじめファイルに書いておき、まとめて実行させるのがシェルスクリプト。", "対話的シェルはその場その場で1行ずつ打ち込む使い方で、設問が指す「先に全部書く」使い方とは逆。", "システムコールはアプリがカーネルに作業を依頼する窓口であり、手順をまとめて書くこととは別の仕組み。", "パイプラインは複数のコマンドをつなげて処理を流す仕組みで、手順をファイルにまとめること自体を指す言葉ではない。"]}'),

  ('linux-q10', 'シェルとコマンドの正体',
   '「ターミナル」「シェル」「コマンド」という3つの言葉の関係を、最も正確に説明しているものはどれか。',
   NULL::text,
   '["ターミナルは入出力の窓口、シェルはその中で動くプログラム、コマンドはシェルに渡す1つの指示", "ターミナルとシェルは同じものを指す別名で、コマンドだけが別の存在", "コマンドがシェルを内部に持ち、シェルがさらにターミナルを内部に持つ入れ子構造になっている", "3つとも同じ1つのプログラムを異なる場面ごとに呼び分けているだけである"]',
   0, '[0]', 'single',
   '{"asked": "ターミナル・シェル・コマンドという3つの言葉の役割分担を問う問題。", "point": "窓口（ターミナル）・担当者（シェル）・お願いごと（コマンド）、の3層で分けて覚える。", "kid": "ターミナルは画面の窓口の箱、シェルはその箱の中で働いている担当者（プログラム）、コマンドはその担当者に渡す「これをやって」という1つのお願い。3つとも別の存在。", "eg": "窓口の建物（ターミナル）、そこで働く受付の人（シェル）、お客が紙に書いて渡す依頼書（コマンド）、と考えるとそれぞれの役割がはっきり分かれる。", "terms": [["ターミナル", "文字の入出力をやり取りする画面・窓口"], ["シェル", "コマンドを解釈し実行するプログラム"], ["コマンド", "シェルに渡す1つの指示"]], "think": "なぜこの3つを混同しやすいのかがカギ。ふだん私たちは「ターミナルを開いてコマンドを打つ」と一続きに体験するので、間にいるシェルの存在を意識しにくい。しかし実際にはターミナルというアプリの中でシェルという別のプログラムが動いており、シェルがコマンドという1つ1つの指示を受け取って処理している、という3層構造になっている。この区別ができると、「シェルを変える」「同じターミナルで違うシェルを試す」といった話が理解しやすくなる。", "vs": "「ターミナル＝シェル」という混同が最も起きやすい。ターミナルは窓口（アプリ）、シェルはその中身（プログラム）という別レイヤーの話であることを区別する。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"300\" height=\"100\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"170\" y=\"36\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ターミナル＝画面と入出力の窓口（箱）</text><rect x=\"45\" y=\"50\" width=\"250\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"170\" y=\"69\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">シェル＝箱の中で動くプログラム（bash等）</text><rect x=\"70\" y=\"90\" width=\"200\" height=\"22\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170\" y=\"105\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コマンド＝シェルに渡す1つの指示</text></svg>", "opt": ["正解。ターミナルは窓口、シェルはその中で動くプログラム、コマンドはシェルへの1つの指示という3層構造。", "ターミナルとシェルは別のソフトウェアであり、同じものの別名ではない。", "コマンドがシェルを内部に持つ、シェルがターミナルを内部に持つという入れ子構造ではない。", "3つはそれぞれ別の役割を持つ別個の存在で、同じ1つのプログラムの呼び分けではない。"]}'),

  ('linux-q11', 'シェルとコマンドの正体',
   'ターミナルに `yuu@mac ~/project $` のような文字列が表示され、次の入力を待っている状態になる。この表示を一般に何と呼び、何を意味しているか。',
   NULL::text,
   '["プロンプト。シェルが入力を受け付ける準備ができたことを示す合図", "エラーメッセージ。何らかの異常が起きたことを知らせる警告表示", "コメント。人間が後から読むための説明書きで、シェルには無視される", "ログ。過去に実行したコマンドの履歴をまとめて表示したもの"]',
   0, '[0]', 'single',
   '{"asked": "ターミナルに表示される `$` などの文字列の名前と意味を問う問題。", "point": "プロンプト＝「今どこにいて、次の入力を待っています」という状態表示。", "kid": "`yuu@mac ~/project $` のような表示はプロンプトと呼ばれ、「今このユーザーで、この場所にいて、次のコマンドを打てる準備ができています」ということをシェルが教えてくれている合図。", "eg": "レストランで店員が「ご注文はお決まりですか？」と聞いてくる場面に近い。それ自体が料理（実行結果）ではなく、「次、何をお願いしますか」という受付の合図。", "terms": [["プロンプト", "シェルが入力待ちであることを示す表示。ユーザー名・場所・記号などを含む"]], "think": "なぜプロンプトに場所やユーザー名が含まれているのかがカギ。ターミナルの中では、今どのユーザーとしてログインしていて、ディレクトリ木構造のどこにいるかによって、同じコマンドでも結果が変わることがある。プロンプトにその情報を表示しておくことで、コマンドを打つ前に「自分は今どこで何をしようとしているか」を確認できる。これは、間違った場所でファイルを消してしまうといった事故を防ぐ手がかりにもなる。", "vs": "エラーメッセージと混同しないこと。エラーは何かがうまくいかなかったときに出る文で、プロンプトは正常な待機状態を示す表示という違いがある。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"40\" width=\"300\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"35\" y=\"65\" font-size=\"10\" fill=\"#60a5fa\" text-anchor=\"start\" font-weight=\"normal\">yuu@mac ~/project $</text><text x=\"170\" y=\"20\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">今の準備ができた、という合図</text><text x=\"170\" y=\"100\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ユーザー名 / 場所 / 入力待ちの印が読み取れる</text></svg>", "opt": ["正解。プロンプトと呼ばれ、シェルが入力待ちであることを示す合図。", "エラーメッセージは異常時にのみ表示されるもので、通常の入力待ち表示とは別物。", "コメントは人間向けの説明書きであり、シェルが状態を示すために自動表示するものではない。", "ログは過去のコマンド履歴の記録であり、現在の入力待ち状態を示すものではない。"]}'),

  ('linux-q12', 'ファイルシステムの本質',
   'Linuxのファイルとディレクトリは、すべてある1つの場所を頂点にして枝分かれしていく形で管理されている。この頂点となる、すべての出発点にあたるディレクトリを何と呼ぶか。',
   NULL::text,
   '["ルートディレクトリ（/）", "ホームディレクトリ", "カレントディレクトリ", "テンポラリディレクトリ"]',
   0, '[0]', 'single',
   '{"asked": "すべてのディレクトリの出発点にあたる頂点の名前を問う問題。", "point": "ファイルシステムは木構造。その根っこ（頂点）が / という1つの場所。", "kid": "Linuxのファイルやディレクトリは、木のように1つの根っこから枝分かれして広がっている。その根っこにあたる、すべての出発点のディレクトリを「/」と書き、ルートディレクトリと呼ぶ。", "eg": "家系図の一番上にいる先祖のようなもの。どんなに枝分かれした子孫（ディレクトリやファイル）も、たどっていけば必ずこの1人の先祖（/）にたどり着く。", "terms": [["ルートディレクトリ", "すべてのディレクトリ・ファイルの出発点。記号は「/」"], ["木構造", "1つの根から枝分かれして広がっていくデータの並べ方"]], "think": "なぜ出発点が1つに決まっているのかがカギ。もし出発点がバラバラだと、「このファイルはどこにあるか」を説明する方法が人によって変わってしまい、指示が通じなくなる。全員が同じ1つの根っこ（/）から数えることに決めておけば、パスという1本の道筋でどのファイルの場所も一意に言い表せる。", "vs": "ホームディレクトリと混同しやすいが、ホームディレクトリは「自分専用の作業場所（/home/ユーザー名など）」で、木構造全体の頂点ではなく、あくまで木の途中にある1つの枝にすぎない。", "viz": "<svg viewBox=\"0 0 340 185\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"150\" y=\"15\" width=\"40\" height=\"22\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"170\" y=\"30\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"bold\">/</text><line x1=\"170\" y1=\"37\" x2=\"90\" y2=\"60\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"170\" y1=\"37\" x2=\"170\" y2=\"60\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"170\" y1=\"37\" x2=\"250\" y2=\"60\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><rect x=\"60\" y=\"60\" width=\"60\" height=\"22\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"90\" y=\"75\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">home</text><rect x=\"140\" y=\"60\" width=\"60\" height=\"22\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"170\" y=\"75\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">etc</text><rect x=\"220\" y=\"60\" width=\"60\" height=\"22\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"250\" y=\"75\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">var</text><line x1=\"90\" y1=\"82\" x2=\"90\" y2=\"105\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><rect x=\"55\" y=\"105\" width=\"70\" height=\"22\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"90\" y=\"120\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">yuu</text><line x1=\"90\" y1=\"127\" x2=\"90\" y2=\"150\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><rect x=\"35\" y=\"150\" width=\"110\" height=\"22\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1\"/><text x=\"90\" y=\"165\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">project</text></svg>", "opt": ["正解。すべてのディレクトリ・ファイルの出発点となる頂点で、記号は「/」。", "ホームディレクトリは各ユーザー専用の作業場所で、木構造全体の頂点ではなく途中の枝の1つ。", "カレントディレクトリは「今自分がいる場所」を指す言葉で、全体の出発点という意味ではない。", "テンポラリディレクトリは一時ファイルを置く場所の1つで、木構造全体の頂点という役割は持たない。"]}'),

  ('linux-q13', 'ファイルシステムの本質',
   '今 `/home/yuu/project` というディレクトリにいるとき、`/home/yuu/data` という書き方と `./data` という書き方は、どちらも同じ場所を指すことがある。この2つの書き方の違いを最も正確に説明しているものはどれか。',
   NULL::text,
   '["前者はルートから数える絶対パス、後者は今いる場所から数える相対パス", "前者はファイル専用の書き方、後者はディレクトリ専用の書き方で、指せる対象が違う", "前者は読み取り専用の書き方、後者は書き込み可能な場所だけを指す書き方", "前者は他のユーザーには見えない書き方、後者は誰にでも見える書き方"]',
   0, '[0]', 'single',
   '{"asked": "絶対パスと相対パスという2つの道筋の書き方の違いを問う問題。", "point": "ルート（/）から数えるか、今いる場所から数えるかの違いだけ。", "kid": "`/home/yuu/data` はルート（一番上の根っこ）から数えた道筋（絶対パス）。`./data` は「今いる場所」から数えた道筋（相対パス）。今いる場所が変われば、相対パスの意味も変わる。", "eg": "友達に待ち合わせ場所を伝えるとき、「東京駅から南口を出て…」（絶対パス）と説明する方法と、「今いる場所からまっすぐ進んで…」（相対パス）と説明する方法があるのに似ている。どちらも同じ場所を指せるが、基準点が違う。", "terms": [["絶対パス", "ルートディレクトリ（/）を基準にした道筋の書き方"], ["相対パス", "今いる場所（カレントディレクトリ）を基準にした道筋の書き方"]], "think": "なぜ2種類の書き方が要るのかがカギ。絶対パスはどこにいても同じ場所を指せるので確実だが、長くなりがち。相対パスは今いる場所の近くを指すときに短く書けて楽だが、今いる場所が変わると指す先も変わってしまう。用途に応じて使い分けられるよう、両方の書き方が用意されている。", "vs": "「相対パスはファイル専用、絶対パスはディレクトリ専用」という誤解に注意。どちらの書き方でもファイル・ディレクトリの両方を指すことができ、違いはあくまで基準点（ルートか今の場所か）だけ。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">今いる場所: /home/yuu/project</text><rect x=\"20\" y=\"30\" width=\"145\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"92\" y=\"48\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"bold\">絶対パス</text><text x=\"92\" y=\"65\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">/home/yuu/data</text><rect x=\"175\" y=\"30\" width=\"145\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"247\" y=\"48\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"bold\">相対パス</text><text x=\"247\" y=\"65\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">./data</text><text x=\"170\" y=\"100\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">どちらも「/」から始まるか、今の場所から始まるかの違い</text></svg>", "opt": ["正解。ルートから数えるのが絶対パス、今いる場所から数えるのが相対パス。", "どちらの書き方もファイル・ディレクトリの両方を指すことができ、対象の種類による使い分けではない。", "読み取り専用・書き込み可能という権限の区別とは無関係で、パスの書き方だけの話。", "他人に見えるかどうかという公開範囲の区別とは無関係で、パスの書き方だけの話。"]}'),

  ('linux-q14', 'ファイルシステムの本質',
   'Linuxでは「ディレクトリもファイルの一種である」としばしば言われる。この説明が指している、ディレクトリの中身の正体として最も適切なものはどれか。',
   NULL::text,
   '["そのディレクトリの中にある名前の一覧表（名簿）が書き込まれたデータ", "画面に表示するための専用のアイコン画像データ", "そのディレクトリを開いた回数を記録したカウンター", "ディレクトリの中に入っているファイルの合計サイズを示す数値だけ"]',
   0, '[0]', 'single',
   '{"asked": "「ディレクトリもファイルの一種」という説明が指す、ディレクトリの中身の正体を問う問題。", "point": "ディレクトリの中身は「名前の一覧表」というデータそのもの。", "kid": "ふつうのファイルの中身が文章や写真のデータであるのに対し、ディレクトリというファイルの中身は「この中にはこういう名前のものが入っていますよ」という一覧表（名簿）のデータになっている。", "eg": "ふつうのファイルは1冊のノート、ディレクトリはそのノートたちが並ぶ「本棚の背表紙の一覧が書かれた目録カード」のようなもの。目録カード自体も1枚の紙（データ）であることに変わりはない。", "terms": [["ディレクトリエントリ", "ディレクトリの中身として記録されている、名前と実体の対応の一覧"]], "think": "なぜ「ディレクトリもファイル」と言えるのかがカギ。OSからすると、データが書き込まれた場所という点でファイルもディレクトリも扱いは同じ。違いは中身の意味づけだけで、ふつうのファイルは自由な内容、ディレクトリは「この中の名前一覧」という決まった形式のデータが書き込まれている、という違いにすぎない。この理解があると、「ディレクトリを開く」という操作が、実は「一覧表というデータを読み取っている」だけだと分かる。", "vs": "「ディレクトリは特別な入れ物で、ファイルとはまったく別の仕組み」という誤解に注意。実体としては両方とも同じ「ファイルという仕組み」の上に成り立っている。", "viz": "<svg viewBox=\"0 0 340 115\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"60\" y=\"30\" width=\"90\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"105\" y=\"46\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ふつうのファイル</text><text x=\"105\" y=\"60\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">中身＝データ</text><rect x=\"190\" y=\"30\" width=\"90\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"235\" y=\"46\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ディレクトリ</text><text x=\"235\" y=\"60\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">中身＝名前の一覧表</text><text x=\"170\" y=\"95\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">どちらも「名前つきの中身」という点では同じファイルの仲間</text></svg>", "opt": ["正解。ディレクトリの中身は、その中にある名前の一覧表というデータそのもの。", "アイコン画像は画面表示のための見た目のデータで、ディレクトリの中身の正体とは別。", "開いた回数のカウンターという情報は、ディレクトリの基本的な中身には含まれない。", "合計サイズの数値だけでなく、実際には名前の一覧という情報そのものが中身になっている。"]}'),

  ('linux-q15', 'ファイルシステムの本質',
   '`memo.txt` というファイルと、拡張子のない `memo` というファイルがあり、どちらも中身は同じ文章だとする。OS（ファイルシステム）自身にとって、この2つの扱いの違いとして最も適切なものはどれか。',
   NULL::text,
   '["OSにとってはどちらも同じ「ファイル」で、扱いを区別しない", "拡張子が無いファイルは、OSの機能によって自動的に開けなくなる", "拡張子が無いファイルは保存容量が半分になる", "拡張子はOSがファイルの中身を暗号化するかどうかを決める合図である"]',
   0, '[0]', 'single',
   '{"asked": "拡張子の有無がOS自身にとってどういう意味を持つかを問う問題。", "point": "拡張子はただの名前の飾り。OS自身は拡張子で中身の扱いを変えない。", "kid": "`.txt` のような拡張子は、人間や一部のアプリが「これは文章ファイルだな」と見分けるための目印にすぎない。OS自身にとっては、拡張子があってもなくても、同じ「名前のついたデータ」というだけの扱いになる。", "eg": "洋服のタグ（拡張子）のようなもの。タグに「Tシャツ」と書いてあっても無くても、服（ファイル）そのものの中身や着心地は変わらない。タグは人間が仕分けるための目印にすぎない。", "terms": [["拡張子", "ファイル名の最後に付ける「.txt」のような、種類を示すための目印の文字列"]], "think": "なぜ拡張子が単なる飾りなのかがカギ。ファイルの実体は、中に書かれているデータそのもの。OSはファイルを保存・読み込みする際、名前がどうであれ同じ手順で扱う。一部のアプリ（画像ビューアなど）が「拡張子を見て開き方を選ぶ」という便利な工夫をしているだけで、OS自身がファイル名の一部を特別扱いしているわけではない。QAの現場でも、拡張子を書き換えただけでは中身は変わらない、という前提を理解しておくとファイル関連のバグ調査がしやすい。", "vs": "「拡張子を変えればファイルの種類そのものが変わる」という誤解に注意。拡張子を変えても中身のデータは変わらず、単に目印の文字列が変わるだけ。", "viz": "<svg viewBox=\"0 0 340 118\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"60\" y=\"30\" width=\"100\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"110\" y=\"49\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">memo.txt</text><rect x=\"180\" y=\"30\" width=\"100\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"230\" y=\"49\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">memo（拡張子なし）</text><text x=\"170\" y=\"80\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">中身が同じ文章なら、OSにとってはどちらも同じ「ファイル」</text><text x=\"170\" y=\"98\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">拡張子は人間・アプリへの目印であって、OSへの命令ではない</text></svg>", "opt": ["正解。OSにとっては拡張子の有無に関わらず、どちらも同じ「ファイル」として扱われる。", "拡張子の有無によってOSが自動的に開けなくする機能は存在しない。", "拡張子の有無は保存容量とは無関係で、容量が変わることはない。", "拡張子は暗号化の合図ではなく、単なる名前の一部の目印にすぎない。"]}'),

  ('linux-q16', 'ファイルシステムの本質',
   'ファイルには「名前」と、その中身を実際に指し示す「inode」と呼ばれる管理情報が別々に存在する。この仕組みから導かれることとして最も適切なものはどれか。',
   NULL::text,
   '["同じ中身(inode)に、別の名前をもう1つ追加でつけられる", "ファイルの名前を変更すると、中身のデータも必ず作り直される", "inodeは画面に表示するアイコンの絵そのものである", "ファイル名を消すと、同時にディスクの容量が自動的に2倍になる"]',
   0, '[0]', 'single',
   '{"asked": "ファイル名とinode（中身の実体）が別々の仕組みであることから何が言えるかを問う問題。", "point": "名前は中身への「札」。同じ中身に複数の名前(札)を結びつけられる。", "kid": "ファイルの「名前」と「中身の実体（inode）」は別のもの。名前は中身への案内札のようなもので、同じ中身に対して別の案内札をもう1枚結びつけることができる（これをハードリンクと呼ぶ）。", "eg": "1つの荷物（中身・inode）に、送り主用のラベルと受取人用のラベルという2枚の名札（名前）を貼るようなもの。ラベルは2枚あっても、中の荷物は同じ1つ。", "terms": [["inode", "ファイルの中身の実体を管理する情報。名前とは別に存在する"], ["ハードリンク", "同じinodeに対して複数の名前をつける仕組み"]], "think": "なぜ名前と中身を分けて管理しているのかがカギ。もし名前そのものが中身と一体だったら、1つの中身に複数の呼び方をさせることができない。名前を「札」として中身（inode）とは別に扱うことで、同じデータに複数の名前で同時にアクセスできたり、名前だけを変更しても中身はそのまま残せたりする柔軟さが生まれる。", "vs": "「ファイル名を変えると中身も作り直される」という誤解に注意。名前は札の付け替えにすぎず、中身（inode）のデータ自体はそのまま。", "viz": "<svg viewBox=\"0 0 340 110\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"40\" y=\"40\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"85\" y=\"59\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">名前: report.txt</text><rect x=\"210\" y=\"40\" width=\"90\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"255\" y=\"59\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">中身の実体(inode)</text><line x1=\"130\" y1=\"55\" x2=\"210\" y2=\"55\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><path d=\"M 204 51 L 210 55 L 204 59\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"170\" y=\"90\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">名前は中身への「札」。同じ中身に別の名前(札)を足せる</text></svg>", "opt": ["正解。同じinode（中身）に対して、別の名前をもう1つ追加でつけることができる。", "名前の変更は札の付け替えにすぎず、中身のデータが作り直されるわけではない。", "inodeは中身を指し示す管理情報であり、画面に表示するアイコンの絵そのものではない。", "ファイル名を消しても容量が自動的に2倍になるという仕組みは存在しない。"]}'),

  ('linux-q17', 'ファイルシステムの本質',
   'USBメモリなどの別の記憶装置を挿すと、そのUSBメモリの中身が `/mnt/usb` のような形で、既存のディレクトリの木構造の中の1つの枝として現れる。この仕組みを何と呼ぶか。',
   NULL::text,
   '["マウント", "コンパイル", "フォーマット", "バックアップ"]',
   0, '[0]', 'single',
   '{"asked": "別の記憶装置を既存のディレクトリ木構造の1枝として組み込む仕組みの名前を問う問題。", "point": "別々の記憶装置を、1本の木構造の枝として接ぎ木する操作がマウント。", "kid": "USBメモリの中身は、本来はパソコン本体のディスクとは別物。でも「マウントする」という操作をすると、そのUSBメモリの中身が `/mnt/usb` のような形で、いつもの1本の木構造の中の1つの枝として顔を出してくれる。", "eg": "よその庭にある木の枝を、自分の庭の木に接ぎ木するイメージ。接ぎ木した後は、見た目には自分の庭の木の一部として枝が伸びているように見える。", "terms": [["マウント", "別の記憶装置を、既存のディレクトリ木構造の1枝として組み込む操作"], ["マウントポイント", "接ぎ木された枝が生える場所（例: /mnt/usb）"]], "think": "なぜ木構造に接ぎ木するという形を取るのかがカギ。ファイルシステムはルート（/）を頂点にした1本の木として道筋（パス）を表す仕組みになっている。もし別の記憶装置ごとに全く別の道筋の体系を使うと、パスの書き方が装置によってバラバラになってしまう。マウントという仕組みで既存の木構造の1枝として組み込むことで、USBメモリの中のファイルも、パソコン本体のファイルも、同じ1本のパスの体系で指せるようになる。", "vs": "フォーマットと混同しやすいが、フォーマットは記憶装置の中身を使える状態に初期化する作業で、マウントは初期化済みの装置を木構造に接ぎ木して使えるようにする作業という違いがある。", "viz": "<svg viewBox=\"0 0 340 155\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"150\" y=\"15\" width=\"40\" height=\"22\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1\"/><text x=\"170\" y=\"30\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"bold\">/</text><line x1=\"170\" y1=\"37\" x2=\"120\" y2=\"60\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"170\" y1=\"37\" x2=\"220\" y2=\"60\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><rect x=\"90\" y=\"60\" width=\"60\" height=\"22\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"120\" y=\"75\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">home</text><rect x=\"190\" y=\"60\" width=\"60\" height=\"22\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1\"/><text x=\"220\" y=\"75\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">mnt</text><line x1=\"220\" y1=\"82\" x2=\"220\" y2=\"100\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><rect x=\"170\" y=\"100\" width=\"100\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\"/><text x=\"220\" y=\"117\" font-size=\"8\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">USBの中身がここに</text><text x=\"170\" y=\"140\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">別の記憶装置を、木の1枝として接ぎ木する＝マウント</text></svg>", "opt": ["正解。別の記憶装置を、既存のディレクトリ木構造の1つの枝として組み込む仕組み。", "コンパイルはソースコードを実行ファイルに変換する作業で、記憶装置を組み込む仕組みとは別物。", "フォーマットは記憶装置を使える状態に初期化する作業で、木構造への組み込み自体を指す言葉ではない。", "バックアップはデータの複製を取っておく作業で、記憶装置を木構造に組み込む仕組みとは別物。"]}'),

  ('linux-q18', 'ファイルシステムの本質',
   'QAの仕事で「テスト実行スクリプトを `./run_tests.sh` と `/opt/project/run_tests.sh` のどちらでも動かせるようにしてほしい」と頼まれたとする。この2つの指定方法の関係として最も適切な理解はどれか。',
   NULL::text,
   '["前者は相対パス、後者は絶対パスで基準点が違うだけ。実体が同じなら同じファイルを実行する", "前者は読み取り専用、後者は実行専用として、それぞれ別の権限で扱われる", "前者はテスト用の一時ファイル、後者は本番用の正式ファイルという、別々の実体を指す", "後者のようなパスはネットワーク越しのサーバー上のファイルにしか使えない"]',
   0, '[0]', 'single',
   '{"asked": "実務でよく出会う相対パス・絶対パスの使い分けを、パスの基本理解から考えさせる問題。", "point": "ルートから数えるか、今いる場所から数えるかの違いだけで、指す実体は同じにもなりうる。", "kid": "`./run_tests.sh` は「今いる場所からたどった道筋」、`/opt/project/run_tests.sh` は「ルートからたどった道筋」。今いる場所が `/opt/project` なら、この2つは結局同じファイルを指している。", "eg": "待ち合わせ場所を「ここからまっすぐ」（相対パス）と言うか、「東京駅から〜」（絶対パス）と言うかの違いのようなもの。言い方は違っても、指している場所そのものは同じにできる。", "terms": [["相対パス", "今いる場所を基準にした道筋の書き方"], ["絶対パス", "ルート（/）を基準にした道筋の書き方"]], "think": "なぜ実務でこの区別を意識する必要があるのかがカギ。テスト自動化のスクリプトをCIサーバーなど「今いる場所」が変わりうる環境で動かす場合、相対パスは実行する場所によって指す先が変わってしまう危険がある。絶対パスは常に同じ場所を指すので確実だが、環境ごとに配置場所が違うと逆に困ることもある。どちらのパスの仕組みも「基準点が違うだけ」と理解しておくと、CIでパスが見つからないというありがちなバグの原因を切り分けやすくなる。", "vs": "「相対パスと絶対パスは別々のファイルを指す」という誤解に注意。基準点が違うだけで、条件がそろえば同じ実体を指すことができる。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">今いる場所: /home/yuu/project</text><rect x=\"20\" y=\"30\" width=\"145\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1\"/><text x=\"92\" y=\"48\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"bold\">絶対パス</text><text x=\"92\" y=\"65\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">/home/yuu/data</text><rect x=\"175\" y=\"30\" width=\"145\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1\"/><text x=\"247\" y=\"48\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"bold\">相対パス</text><text x=\"247\" y=\"65\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">./data</text><text x=\"170\" y=\"100\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">どちらも「/」から始まるか、今の場所から始まるかの違い</text></svg>", "opt": ["正解。相対パスと絶対パスは基準点が違うだけで、指す実体が同じなら同じファイルを実行する。", "読み取り専用・実行専用という権限の区別は、パスの書き方（相対か絶対か）とは無関係。", "テスト用・本番用という区別はパスの書き方では決まらず、別々の実体を指すとは限らない。", "絶対パスはネットワーク越しのサーバーに限らず、手元のコンピュータのファイルを指すのにも使う。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'linux-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
